class TestVoIpnumberModel(VoIPFixtures, BloomerpModelTestCase):
    model = VoIPNumber

    def create_assignees(self, count: int) -> list[AbstractBloomerpUser]:
        """Create eligible staff to exercise assignment limits through real relations."""
        return [
            get_user_model().objects.create(username=f"assigned_{index}", is_staff=True)
            for index in range(count)
        ]

    def test_twilio_limit_applies_to_forward_and_reverse_additions(self) -> None:
        """Reject the eleventh user from either relation while allowing duplicate adds."""
        self.prepare_voip()
        users = self.create_assignees(10)
        self.number.assigned_users.add(*users[:9])
        self.number.assigned_users.add(users[0])
        self.assertEqual(self.number.assigned_users.count(), 10)
        with self.assertRaises(ValidationError), transaction.atomic():
            self.number.assigned_users.add(users[9])
        with self.assertRaises(ValidationError), transaction.atomic():
            users[9].voip_numbers.add(self.number)
        self.assertEqual(self.number.assigned_users.count(), 10)

    def test_model_form_rejects_over_limit_replacement_atomically(self) -> None:
        """Enforce the same limit when the generic model form saves assigned_users."""
        self.prepare_voip()
        users = self.create_assignees(11)
        form_class = modelform_factory(
            VoIPNumber, form=BloomerpModelForm, fields=["assigned_users"]
        )
        form = form_class(
            data={"assigned_users": [user.pk for user in users]}, instance=self.number
        )
        self.assertTrue(form.is_valid(), form.errors)
        with self.assertRaises(ValidationError), transaction.atomic():
            form.save()
        self.assertEqual(list(self.number.assigned_users.all()), [self.normal_user])

    def test_provider_without_limit_allows_more_than_ten_users(self) -> None:
        """Keep the constraint opt-in rather than tied to all VoIP lines."""
        self.prepare_voip()
        provider = replace(TWILIO_PROVIDER, key="unlimited", max_assigned_users=None)
        with patch.dict(VOIP_PROVIDER_REGISTRY._registry, {provider.key: provider}):
            connection = VoIPConnection.objects.create(
                name="Unlimited carrier", provider=provider.key,
                external_account_id="unlimited-account",
            )
            number = VoIPNumber.objects.create(
                connection=connection, number="+32470000009",
                provider_number_id="unlimited-line",
            )
            number.assigned_users.add(*self.create_assignees(11))
            self.assertEqual(number.assigned_users.count(), 11)

    def test_assignment_limit_comes_from_each_provider_definition(self) -> None:
        """Honor an extension provider's own limit without a Twilio-specific branch."""
        self.prepare_voip()
        provider = replace(TWILIO_PROVIDER, key="limited", max_assigned_users=2)
        with patch.dict(VOIP_PROVIDER_REGISTRY._registry, {provider.key: provider}):
            connection = VoIPConnection.objects.create(
                name="Limited carrier", provider=provider.key,
                external_account_id="limited-account",
            )
            number = VoIPNumber.objects.create(
                connection=connection, number="+32470000009",
                provider_number_id="limited-line",
            )
            users = self.create_assignees(3)
            number.assigned_users.add(*users[:2])
            with self.assertRaises(ValidationError), transaction.atomic():
                number.assigned_users.add(users[2])
            self.assertEqual(number.assigned_users.count(), 2)

    def get_test_scenarios(self) -> list[ModelScenario[VoIPNumber]]:
        # Add only the scenarios this class needs.
        """Define declarative scenarios for this generated test case."""
        return [
            ModelScenario(
                name="Reject duplicate line within account",
                preparation=self.prepare_voip,
                create_args=self.duplicate_args,
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
            ModelScenario(
                name="Allow same provider ID in another account",
                preparation=self.prepare_voip,
                create_args=self.other_args,
            ),
        ]

    def duplicate_args(self) -> dict[str, Any]:
        """Attempt to duplicate the existing line's scoped identity."""
        return {
            "connection": self.connection,
            "number": self.number.number,
            "provider_number_id": self.number.provider_number_id,
        }

    def other_args(self) -> dict[str, Any]:
        """Reuse an opaque number identifier under another configured account."""
        return {**self.duplicate_args(), "connection": self.other_connection}
